style.css:
/* Global Cyber Style - Simplified and Red Theme */
@font-face {
    font-family: 'CyberFont';
    src: url('https://fonts.cdnfonts.com/s/15159/CyberpunkRegular.woff') format('woff');
}

body {
    font-family: 'CyberFont', sans-serif !important;
    color: #ff3333 !important; /* Sharp red for text */
    background-color: #000 !important; /* Black background */
    line-height: 1.6; /* Maintain readability */
}

a {
    color: #ff4d4d !important; /* Lighter red for links */
    text-decoration: none !important;
}

a:hover {
    color: #ff6666 !important; /* Softer red for hover effects */
}

button, input, textarea {
    font-family: 'CyberFont', sans-serif !important;
    color: #ff3333 !important;
    background-color: #1a1a1a !important;
    border: 1px solid #ff3333 !important;
    padding: 5px;
}

button:hover {
    background-color: #ff3333 !important;
    color: #000 !important;
    border-color: #ff6666 !important;
}

h1, h2, h3, h4, h5, h6 {
    font-family: 'CyberFont', sans-serif !important;
    color: #ff3333 !important;
}

/* Prevent layout issues */
img, iframe, canvas, video {
    max-width: 100% !important;
    height: auto !important;
}

/* Ensure readability for text-heavy elements */
p, span, div {
    color: #ff3333 !important;
    text-shadow: none !important; /* No excessive glow for clarity */
}

/* Basic box-sizing fix */
* {
    box-sizing: border-box;
}
